func:
const p = msg.payload;
if (!p || p.fraud_probability === undefined) return [null, null, null];
msg.topic = p.risk_tier || 'UNKNOWN';
msg.insertion_id = p.insertion_id;
msg.fraud_probability = p.fraud_probability;
const gaugeMsg = { payload: Math.round(p.fraud_probability * 100) };
const chartMsg = { payload: [{ series: ['Fraud Score'], data: [[{ x: Date.now(), y: p.fraud_probability }]], labels: [''] }] };
return [msg, gaugeMsg, chartMsg];

let n = flow.get('approved_count') || 0;
flow.set('approved_count', ++n);
msg.payload = n;
return msg;

let n = flow.get('review_count') || 0;
flow.set('review_count', ++n);
msg.payload = n;
return msg;

let n = flow.get('declined_count') || 0;
flow.set('declined_count', ++n);
msg.payload = n;
return msg;

const paused = !flow.get('sim_paused');
flow.set('sim_paused', paused);
msg.payload = paused ? '⏸ PAUSED' : '● LIVE';
return msg;

const id = msg.insertion_id;
if (!id) return null;
msg.url = 'http://localhost:8000/admin/shap/' + id;
msg.method = 'POST';
msg.payload = {};
return msg;

const r = msg.payload;
const id = msg.insertion_id;
if (!r || !id || r.detail) {
    node.debug('SHAP unavailable for ' + id + ': ' + (r && r.detail ? r.detail : 'unknown'));
    flow.set('shap_' + id, { image: null, bars: '<p style="color:#666;font-size:12px">' + (r && r.detail ? r.detail : 'SHAP unavailable') + '</p>' });
    return null;
}
const indicators = (r.top_fraud_indicators || []).slice(0, 8);
const rows = indicators.map(function(it) {
    const pct = Math.min(Math.abs(it.shap_value * 300), 150).toFixed(0);
    const color = it.shap_value > 0 ? '#e74c3c' : '#2ecc71';
    return '<div style="display:flex;align-items:center;gap:6px;margin:3px 0;font-size:12px">'
        + '<span style="min-width:160px;color:#ccc;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + it.feature + '</span>'
        + '<div style="background:' + color + ';width:' + pct + 'px;height:12px;border-radius:2px;min-width:2px"></div>'
        + '<span style="color:' + color + '">' + (it.shap_value >= 0 ? '+' : '') + it.shap_value.toFixed(3) + '</span>'
        + '</div>';
}).join('');
const barsHtml = '<div style="padding:8px;background:#0a1018;border-radius:4px">'
    + '<p style="color:#97d4e2;font-size:12px;margin:0 0 8px">Fraud prob: <b>' + (r.prediction_value * 100).toFixed(1) + '%</b> &middot; base: ' + (r.base_value || 0).toFixed(3) + '</p>'
    + rows + '</div>';
flow.set('shap_' + id, { image: r.waterfall_chart_base64 || null, bars: barsHtml });
msg.payload = Date.now();
return msg;

const data = msg.payload;
if (!data || !data.items) { msg.payload = []; return msg; }
msg.payload = data.items.map(function(it) {
    const s = it.event_summary || {};
    const shap = flow.get('shap_' + it.insertion_id) || null;
    return {
        full_id: it.insertion_id,
        id_short: (it.insertion_id || '').slice(0, 10) + '\u2026',
        score: (it.fraud_probability * 100).toFixed(1) + '%',
        category: s.listing_category || '-',
        price: s.listing_price || '-',
        ip_country: s.seon_ip_country || '-',
        tor: !!s.seon_tor,
        vpn: !!s.seon_vpn,
        disposable: !!s.seon_email_disposable,
        queued_at: (it.queued_at || '').slice(11, 19),
        shap_ready: !!shap,
        shap_image: shap ? shap.image : null,
        shap_bars:  shap ? shap.bars  : null
    };
});
return msg;

const p = msg.payload;
if (!p || !p.insertion_id || !p.decision) return null;
msg.url = 'http://localhost:8000/admin/decision/' + p.insertion_id;
msg.method = 'POST';
msg.payload = { decision: p.decision, admin_id: 'admin-1', notes: p.notes || '' };
return msg;

const r = msg.payload;
if (r && r.admin_decision) {
    msg.payload = (r.admin_decision === 'APPROVE' ? '✅ Approved' : '🚫 Declined') + ' — bucket: ' + r.bucket;
} else {
    msg.payload = 'Error: ' + JSON.stringify(r);
}
return msg;

const d = msg.payload || {};
const psi = d.prediction_psi || 0;
const overall = !!d.overall_drift;
const features = d.drifted_features || [];
const dist = d.score_distribution || {};
const featHtml = features.length
    ? '<ul style="color:#e74c3c;margin:0;padding-left:16px">' + features.map(function(f){ return '<li>' + f + '</li>'; }).join('') + '</ul>'
    : '<p style="color:#2ecc71;margin:0">No drifted features</p>';
const histMsg = { payload: [{ series:['Predictions'], data:[[dist['0.0-0.1']||0,dist['0.1-0.3']||0,dist['0.3-0.5']||0,dist['0.5-0.7']||0,dist['0.7-1.0']||0]], labels:['0–0.1','0.1–0.3','0.3–0.5','0.5–0.7','0.7–1.0'] }] };
return [
    { payload: Math.round(psi * 1000) / 10 },
    { payload: d.drift_label || 'COLLECTING DATA' },
    { payload: featHtml },
    histMsg,
    overall ? { payload: '\u26a0\ufe0f CONCEPT DRIFT DETECTED \u2014 PSI: ' + psi.toFixed(3) + '\nAuto-retrain will be triggered.' } : null,
    overall ? { payload: { overall_drift: true, psi: psi } } : null
];

const last = flow.get('last_auto_retrain') || 0;
const now = Date.now();
if (now - last < 5 * 60 * 1000) {
    const remaining = Math.round((5 * 60 * 1000 - (now - last)) / 1000);
    node.warn('Auto-retrain skipped — cooldown: ' + remaining + 's remaining');
    const mins = Math.floor(remaining / 60);
    const secs = remaining % 60;
    return [null, { payload: '\u23f3 ' + mins + 'm ' + secs + 's until auto-retrain' }];
}
flow.set('last_auto_retrain', now);
node.warn('Drift confirmed — triggering auto-retrain');
msg.payload = {};
return [msg, { payload: '' }];

const s = msg.payload || {};
return [
    { payload: s.approved_count || 0 },
    { payload: s.declined_count || 0 },
    { payload: s.pending_retrain_rows || 0 },
    { payload: s.queue_size || 0 }
];

const m = msg.payload || {};
return [
    { payload: m.model_uri || 'not loaded' },
    { payload: m.mlflow_run_id || '-' },
    { payload: (m.mlflow_model_alias || '-').toUpperCase() }
];

const h = msg.payload || {};
const apiOk = h.status === 'healthy';
const modelOk = h.model_loaded === true;
const dot = function(ok, label, sub) {
    const col = ok ? '#2ecc71' : '#e74c3c';
    const icon = ok ? '✔' : '✖';
    return '<div style="display:flex;align-items:center;gap:8px;margin:5px 0">'
        + '<span style="font-size:18px;color:' + col + '">' + icon + '</span>'
        + '<div><div style="color:#e0e0e0;font-size:13px">' + label + '</div>'
        + (sub ? '<div style="color:#888;font-size:11px">' + sub + '</div>' : '')
        + '</div></div>';
};
msg.payload = '<div style="padding:10px">' 
    + dot(apiOk, 'API Server', h.status || 'unknown')
    + dot(modelOk, 'Model Loaded', modelOk ? 'ready' : 'not loaded')
    + dot((h.graph_nodes || 0) > 0, 'Graph Store', (h.graph_nodes || 0) + ' nodes')
    + '</div>';
return msg;

const r = msg.payload || {};
if (r.status === 'triggered') {
    msg.payload = '\ud83d\ude80 Retraining started with ' + r.training_rows + ' rows. Monitor in MLflow \u2192 make register-model';
} else if (r.status === 'insufficient_data') {
    msg.payload = '\u26a0\ufe0f Not enough data: ' + r.rows + ' / ' + r.required + ' rows required.';
} else {
    msg.payload = JSON.stringify(r);
}
return msg;

for (var i = 0; i < 25; i++) {
    node.send({ payload: { scenario: 'HIGH_RISK' } });
}
return null;

const s = msg.payload || {};
const status = s.status || 'idle';
const prev = flow.get('retrain_status_prev') || 'idle';
flow.set('retrain_status_prev', status);

const labels = { idle: '⬜ IDLE', running: '🔄 TRAINING…', completed: '✅ COMPLETED', failed: '❌ FAILED' };
const label = labels[status] || status.toUpperCase();

// Build detail line
let detail = '';
if (s.started_at) detail += 'Started: ' + s.started_at.slice(11,19) + ' UTC';
if (s.finished_at) detail += '  |  Finished: ' + s.finished_at.slice(11,19) + ' UTC';
if (s.training_rows) detail += '  |  Rows: ' + s.training_rows;

// Only fire toast on transitions
let toastMsg = null;
if (prev !== status) {
    if (status === 'running') toastMsg = { payload: '🔄 Retraining in progress… (' + s.training_rows + ' rows)' };
    else if (status === 'completed') toastMsg = { payload: '✅ Retraining completed! Run make register-model to promote.' };
    else if (status === 'failed') toastMsg = { payload: '❌ Retraining failed: ' + (s.error || 'unknown error') };
}

return [
    { payload: label },
    { payload: detail },
    toastMsg,
    (prev !== status && status === 'completed') ? { payload: {} } : null
];

const r = msg.payload || {};
if (r.status !== 'promoted') {
    node.warn('Promote failed: ' + JSON.stringify(r));
    return null;
}
msg._promote_version = r.version;
msg.payload = {};
return msg;

const r = msg.payload || {};
if (r.status !== 'reloaded') {
    node.warn('Reload failed: ' + JSON.stringify(r));
    return [null, null];
}
const toast = { payload: '\ud83d\udd04 Model v' + (msg._promote_version || '?') + ' hot-swapped \u2192 ' + (r.model_uri || 'unknown') };
return [toast, { payload: Date.now() }];

const r = msg.payload || {};
if (r.status !== 'FINISHED') return [null, null, null];
const m = r.metrics || {};
return [
    { payload: m.auc_pr  != null ? m.auc_pr.toFixed(4)  : '\u2014' },
    { payload: m.auc_roc != null ? m.auc_roc.toFixed(4) : '\u2014' },
    { payload: r.run_name || (r.run_id ? r.run_id.slice(0,8) : '\u2014') }
];
